#include "syspulse/native/diagnostics.hpp"
#include <cstdlib>
#include <iostream>
using namespace syspulse::native;
unsigned count=0;void check(bool ok,const char* label){++count;if(!ok){std::cerr<<label<<'\n';std::exit(1);}}
std::string row(const std::string& msg,int pr=4,const std::string& cursor=""){return "{\"MESSAGE\":\""+msg+"\",\"PRIORITY\":\""+std::to_string(pr)+"\""+(cursor.empty()?"":",\"__CURSOR\":\""+cursor+"\"")+"}\n";}
int main(){const char* events[]={"I/O error on disk","EXT4-fs error","SMART health FAIL","Out of memory","swap exhausted","GPU hang","critical temperature","kernel panic","failed to start demo","dpkg: error","DNS timeout","failed password","segfault","unexpected error"};for(unsigned i=0;i<14;++i){auto s=diagnoseJournal(row(events[i]),true,false);check(s.available&&s.records==1&&!s.partial&&s.counts[i]==1,"category");unsigned total=0;for(auto n:s.counts)total+=n;check(total==1,"single precedence");}
 const char* rec[]={"SMART health passed; 0 pending sectors.","SMART: 0 pending sectors, 0 offline uncorrectable sectors.","No errors detected in the RAM test.","Memory pressure has returned to normal.","Previous error resolved; service started successfully.","Previous package error was resolved during recovery.","Connection timed out earlier; link restored.","GPU reset completed successfully; display restored."};for(auto t:rec){auto s=diagnoseJournal(row(t),true,false);check(s.recovered==1,"exact recovery");s=diagnoseJournal(row(t,3),true,false);check(s.recovered==0,"high severity never suppressed");}
 auto s=diagnoseJournal(row("package failed to start"),true,false);check(s.counts[9]==1,"original ordered rules");s=diagnoseJournal(row("normal",3),true,false);check(s.counts[13]==1,"priority fallback");s=diagnoseJournal(row("normal"),true,false);check(s.counts[13]==0,"normal ignored");
 s=diagnoseJournal(row("oom-kill",4,"a")+row("oom-kill",4,"a"),true,false);check(s.records==1&&s.duplicates==1&&s.counts[3]==1,"cursor duplicate");s=diagnoseJournal(row("PRIVATE-SECRET error"),true,false);check(diagnosticReport(s).find("PRIVATE-SECRET")==std::string::npos,"privacy");
 check(!diagnoseJournal(row("kernel panic"),false,false).available,"failed command unavailable");check(!diagnoseJournal("",true,false).available,"empty not healthy");check(diagnoseJournal("broken\n",true,false).malformed==1,"malformed");check(diagnoseJournal("{\"MESSAGE\":[1,2]}\n",true,false).malformed==1,"binary message");check(diagnoseJournal("{\"MESSAGE\":\"x\",\"PRIORITY\":99}\n",true,false).malformed==1,"bad priority");check(diagnoseJournal(row(std::string(2049,'x')),true,false).oversized==1,"message cap");check(diagnoseJournal(row("error"),true,true).partial,"truncated");check(!diagnoseJournal(std::string(65537,'x'),true,false).available,"input cap");std::string many;for(int i=0;i<257;++i)many+=row("x");check(diagnoseJournal(many,true,false).records==256,"record cap");std::cout<<count<<" diagnostic parity checks passed\n";}
